import { pgSchema, timestamp, uuid } from 'drizzle-orm/pg-core';

/**
 * All of OUR tables live in the `app` schema. Providers (Supabase, Neon) only expose
 * `public` through their auto-generated data APIs, so keeping our tables out of `public`
 * means nothing here is reachable with a browser key. Every table also has Row Level
 * Security switched on with no policies and no grants to anon/authenticated, so even if
 * the schema were ever exposed it would return nothing. The app reads and writes through
 * the server-only database connection (DATABASE_URL), via actions.
 *
 * Other schemas in the database belong to someone else (the auth provider) — never touch them.
 */
export const app = pgSchema('app');

/** Primary key used by every table: a random UUID generated by Postgres. */
export const id = () => uuid('id').primaryKey().defaultRandom();

export const createdAt = () =>
  timestamp('created_at', { withTimezone: true }).notNull().defaultNow();

export const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());
